async function a(t){const n=await fetch(t);if(!n.ok)throw new Error(`HTTP ${n.status} ${n.statusText}`);return await n.json()}async function i(){return a("/api/wiki/tree")}async function e(t){return a(`/api/wiki/page/${encodeURIComponent(t)}`)}async function s(){return a("/api/wiki/graph")}async function r(t){return a(`/api/wiki/backlinks/${encodeURIComponent(t)}`)}async function c(){try{const t=await fetch("/api/wiki/health");if(!t.ok)return null;const n=await t.json();return n.ok&&n.health?n.health:null}catch{return null}}async function o(){const t=await fetch("/api/wiki/semantic-search");if(t.status===404)return null;if(!t.ok)throw new Error(`HTTP ${t.status} ${t.statusText}`);return await t.json()}async function u(t){const n=await fetch("/api/wiki/semantic-search",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({enabled:t})});if(!n.ok)throw new Error(`HTTP ${n.status} ${n.statusText}`);return await n.json()}async function h(){const t=await fetch("/api/wiki/reindex",{method:"POST"});if(!t.ok)throw new Error(`HTTP ${t.status} ${t.statusText}`);return await t.json()}export{i as a,s as b,r as c,c as d,o as e,e as f,h as r,u as s};
